package com.mlserver.inference

import io.ktor.server.application.*
import io.ktor.server.engine.*
import io.ktor.server.netty.*
import io.ktor.server.request.*
import io.ktor.server.response.*
import io.ktor.server.routing.*
import io.ktor.http.content.*
import java.io.File
import java.nio.file.Files
import java.nio.file.Path
import java.security.MessageDigest
import java.util.UUID
import java.util.concurrent.ConcurrentHashMap

data class ModelSession(
    val sessionId: String,
    val modelPath: String,
    val modelFormat: String,
    val metadata: Map<String, String>
)

object SessionRegistry {
    private val sessions = ConcurrentHashMap<String, ModelSession>()
    fun register(session: ModelSession) { sessions[session.sessionId] = session }
    fun get(sessionId: String): ModelSession? = sessions[sessionId]
    fun remove(sessionId: String) { sessions.remove(sessionId) }
}

object ModelValidator {
    private val ALLOWED_FORMATS = setOf("onnx", "tflite", "savedmodel", "torchscript")
    private val MAGIC_BYTES = mapOf(
        "onnx" to byteArrayOf(0x08, 0x00, 0x00, 0x00),
        "tflite" to byteArrayOf(0x54, 0x46, 0x4C, 0x33)
    )

    fun validateFormat(format: String): Boolean = format.lowercase() in ALLOWED_FORMATS

    fun sanitizeFilename(name: String): String {
        return name.replace(Regex("[^a-zA-Z0-9._-]"), "_")
    }

    fun computeChecksum(data: ByteArray): String {
        val digest = MessageDigest.getInstance("SHA-256")
        return digest.digest(data).joinToString("") { "%02x".format(it) }
    }
}

class InferenceEngine {
    private val workDir = File("/tmp/ml_inference")

    init {
        workDir.mkdirs()
    }

    fun prepareModel(session: ModelSession): Result<String> {
        val modelFile = File(session.modelPath)
        if (!modelFile.exists()) return Result.failure(Exception("Model file not found"))
        if (!modelFile.canonicalPath.startsWith(workDir.canonicalPath)) {
            return Result.failure(Exception("Path traversal detected"))
        }
        return Result.success(modelFile.canonicalPath)
    }

    fun runInference(session: ModelSession, inputData: ByteArray): Result<ByteArray> {
        val prepared = prepareModel(session)
        if (prepared.isFailure) return Result.failure(prepared.exceptionOrNull()!!)

        val modelPath = prepared.getOrThrow()
        val outputPath = "${workDir.absolutePath}/${session.sessionId}_output.bin"

        // Build inference command based on model format
        val command = buildInferenceCommand(session, modelPath, outputPath, inputData)
        return executeInference(command, outputPath)
    }

    private fun buildInferenceCommand(
        session: ModelSession,
        modelPath: String,
        outputPath: String,
        inputData: ByteArray
    ): List<String> {
        val baseCmd = mutableListOf("ml-runtime", "--model", modelPath, "--output", outputPath)

        // Apply model-specific optimizations from metadata
        session.metadata.forEach { (key, value) ->
            when (key) {
                "optimization_level" -> baseCmd.addAll(listOf("--opt-level", sanitizeArgValue(value)))
                "num_threads" -> baseCmd.addAll(listOf("--threads", value.toIntOrNull()?.coerceIn(1, 16)?.toString() ?: "4"))
                "device" -> baseCmd.addAll(listOf("--device", sanitizeArgValue(value)))
                "custom_ops_path" -> {
                    // Allow custom operator libraries - validated path
                    val opsFile = File(value)
                    if (opsFile.exists() && opsFile.extension == "so") {
                        baseCmd.addAll(listOf("--custom-ops", opsFile.canonicalPath))
                    }
                }
            }
        }

        // Add post-processing hook if specified
        val postProcess = session.metadata["post_process"]
        if (postProcess != null) {
            baseCmd.addAll(listOf("--post-hook", resolvePostProcessor(postProcess)))
        }

        return baseCmd
    }

    private fun sanitizeArgValue(value: String): String {
        // Remove shell metacharacters
        return value.replace(Regex("[;&|`\$(){}\[\]<>!\\\"'\n\r]"), "")
    }

    private fun resolvePostProcessor(name: String): String {
        // Map friendly names to processor scripts
        val processors = mapOf(
            "softmax" to "/opt/ml/processors/softmax.sh",
            "argmax" to "/opt/ml/processors/argmax.sh",
            "normalize" to "/opt/ml/processors/normalize.sh",
            "topk" to "/opt/ml/processors/topk.sh"
        )
        return processors[name] ?: "/opt/ml/processors/${name}.sh"
    }

    private fun executeInference(command: List<String>, outputPath: String): Result<ByteArray> {
        return try {
            val process = ProcessBuilder(command)
                .directory(File("/tmp/ml_inference"))
                .redirectErrorStream(true)
                .start()

            val exitCode = process.waitFor()
            if (exitCode != 0) {
                val error = process.inputStream.bufferedReader().readText()
                return Result.failure(Exception("Inference failed: $error"))
            }

            val outputFile = File(outputPath)
            if (outputFile.exists()) {
                Result.success(outputFile.readBytes())
            } else {
                Result.failure(Exception("No output produced"))
            }
        } catch (e: Exception) {
            Result.failure(e)
        }
    }
}

fun Application.configureRouting() {
    val engine = InferenceEngine()

    routing {
        post("/api/v1/models/upload") {
            val multipart = call.receiveMultipart()
            var modelBytes: ByteArray? = null
            var format: String = "onnx"
            val metadata = mutableMapOf<String, String>()

            multipart.forEachPart { part ->
                when (part) {
                    is PartData.FileItem -> {
                        modelBytes = part.streamProvider().readBytes()
                    }
                    is PartData.FormItem -> {
                        when (part.name) {
                            "format" -> format = part.value
                            else -> {
                                if (part.name?.startsWith("meta_") == true) {
                                    metadata[part.name!!.removePrefix("meta_")] = part.value
                                }
                            }
                        }
                    }
                    else -> {}
                }
                part.dispose()
            }

            if (modelBytes == null) {
                call.respondText("No model file provided", status = io.ktor.http.HttpStatusCode.BadRequest)
                return@post
            }

            if (!ModelValidator.validateFormat(format)) {
                call.respondText("Unsupported format", status = io.ktor.http.HttpStatusCode.BadRequest)
                return@post
            }

            val sessionId = UUID.randomUUID().toString()
            val safeFilename = ModelValidator.sanitizeFilename("${sessionId}.${format}")
            val modelPath = "/tmp/ml_inference/$safeFilename"
            File(modelPath).writeBytes(modelBytes!!)

            val session = ModelSession(sessionId, modelPath, format, metadata)
            SessionRegistry.register(session)

            call.respondText("{\"session_id\": \"$sessionId\", \"checksum\": \"${ModelValidator.computeChecksum(modelBytes!!)}\"}",
                contentType = io.ktor.http.ContentType.Application.Json)
        }

        post("/api/v1/inference/{sessionId}") {
            val sessionId = call.parameters["sessionId"] ?: run {
                call.respondText("Missing session ID", status = io.ktor.http.HttpStatusCode.BadRequest)
                return@post
            }

            val session = SessionRegistry.get(sessionId) ?: run {
                call.respondText("Session not found", status = io.ktor.http.HttpStatusCode.NotFound)
                return@post
            }

            val inputData = call.receive<ByteArray>()
            val result = engine.runInference(session, inputData)

            result.fold(
                onSuccess = { output -> call.respondBytes(output) },
                onFailure = { error ->
                    call.respondText("Inference error: ${error.message}",
                        status = io.ktor.http.HttpStatusCode.InternalServerError)
                }
            )
        }
    }
}

fun main() {
    embeddedServer(Netty, port = 8080) {
        configureRouting()
    }.start(wait = true)
}
